import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def base_network():
    return {
        "y_of_node_m": [0.0, 100.0, 210.0, 220.0, 340.0, 470.0, 480.0, 140.0],
        "x_of_node_m": [0.0, 0.0, 90.0, -70.0, -120.0, 60.0, -170.0, -115.0],
        "nodes_at_link": [[1, 0], [2, 1], [1, 7], [3, 1], [3, 4], [4, 5], [4, 6]],
        "topographic_elevation_m": [0.0, 1.1, 2.5, 2.3, 3.8, 5.0, 5.4, 2.0],
        "bedrock_elevation_m": [0.0, 1.1, 2.5, 2.3, 3.8, 5.0, 5.4, 2.0],
        "reach_length_m": [110.0, 125.0, 95.0, 130.0, 145.0, 160.0, 150.0],
        "channel_width_m": [18.0, 14.0, 10.0, 16.0, 13.0, 11.0, 12.0],
        "flow_depth_m": [0.55, 0.50, 0.45, 0.52, 0.48, 0.46, 0.47],
    }

def base_material(**kw):
    m = {
        "grain_diameter_m": 0.04,
        "sediment_density_kg_m3": 2650.0,
        "abrasion_rate_m_inverse": 0.0,
    }
    m.update(kw)
    return m

def base_experiment(**kw):
    e = {"time_step_s": 90.0, "steps": 4, "bed_porosity": 0.25, "gravity_m_s2": 9.81, "fluid_density_kg_m3": 1000.0}
    e.update(kw)
    return e

def record(specs):
    return [dict(zip(("link", "location", "volume_m3"), s)) for s in specs]

scenarios = {}

# 1. abrasion active, long run so parcels traverse several links and may exit
scenarios["s_abrasion"] = {
    "network": base_network(),
    "material": base_material(abrasion_rate_m_inverse=1.0e-4),
    "experiment": base_experiment(time_step_s=360.0, steps=20),
    "transport_method": "WilcockCrowe",
    "sediment_record": record([
        (5, 0.1, 0.5), (5, 0.6, 0.5), (6, 0.2, 0.4), (6, 0.8, 0.4),
        (2, 0.3, 0.3), (4, 0.5, 0.6),
    ]),
}

# 2. tiny grains + high flow -> more transport, exit to boundary
scenarios["s_exit"] = {
    "network": base_network(),
    "material": base_material(grain_diameter_m=0.005),
    "experiment": base_experiment(time_step_s=300.0, steps=12),
    "transport_method": "WilcockCrowe",
    "sediment_record": record([
        (5, 0.1, 0.5), (6, 0.1, 0.5), (1, 0.9, 0.5), (0, 0.5, 0.5),
    ]),
}

# 3. MPM transport law with abrasion and big gravel
scenarios["s_mpm"] = {
    "network": base_network(),
    "material": base_material(grain_diameter_m=0.08, abrasion_rate_m_inverse=5.0e-5),
    "experiment": base_experiment(time_step_s=180.0, steps=15),
    "transport_method": "MeyerPeterMuller",
    "sediment_record": record([
        (5, 0.5, 0.7), (6, 0.5, 0.7), (3, 0.5, 0.7),
    ]),
}

# 4. mixed grain sizes / densities per parcel
scenarios["s_mixed"] = {
    "network": base_network(),
    "material": base_material(),
    "experiment": base_experiment(time_step_s=120.0, steps=16),
    "sediment_record": [
        {"link": 5, "location": 0.2, "volume_m3": 0.3, "D": 0.01, "density": 2650.0},
        {"link": 5, "location": 0.7, "volume_m3": 0.4, "D": 0.06, "density": 2650.0},
        {"link": 6, "location": 0.3, "volume_m3": 0.25, "D": 0.03, "density": 1800.0},
        {"link": 2, "location": 0.4, "volume_m3": 0.5, "D": 0.001, "density": 2650.0},
    ],
}

# 5. convergent parcels at junction nodes simultaneously, small dt
scenarios["s_junction"] = {
    "network": base_network(),
    "material": base_material(),
    "experiment": base_experiment(time_step_s=45.0, steps=30),
    "sediment_record": record([
        (5, 0.9, 0.3), (6, 0.9, 0.3), (5, 0.95, 0.3), (6, 0.95, 0.3),
    ]),
}

for name, cfg in scenarios.items():
    (ROOT / f"scen_{name}.json").write_text(json.dumps(cfg, indent=2))
    print(name)

