"""Compare fuzz shard JSON outputs candidate vs wheel; report any divergence."""
from __future__ import annotations

import json
import math
import sys
from pathlib import Path

TASK_ROOT = Path(__file__).resolve().parents[1]
seed, count, start, n = sys.argv[1:5]
c = json.loads((TASK_ROOT / "outputs" / "fuzz" / f"cand_{seed}_{count}_{start}_{n}.json").read_text())
w = json.loads((TASK_ROOT / "outputs" / "fuzz" / f"wheel_{seed}_{count}_{start}_{n}.json").read_text())

def isnan(x):
    return isinstance(x, float) and math.isnan(x)

def deep_eq(a, b, path=""):
    if isnan(a) and isnan(b):
        return []
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return [f"{path}: len {len(a)} vs {len(b)}"]
        out = []
        for i, (x, y) in enumerate(zip(a, b)):
            out += deep_eq(x, y, f"{path}[{i}]")
        return out
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a) != set(b):
            return [f"{path}: keys {sorted(set(a) ^ set(b))}"]
        out = []
        for k in a:
            out += deep_eq(a[k], b[k], f"{path}.{k}")
        return out
    if a != b:
        return [f"{path}: {a!r} vs {b!r}"]
    return []

problems = 0
for i, (ca, wa) in enumerate(zip(c, w)):
    diffs = deep_eq(ca, wa, f"scenario{i}")
    if diffs:
        problems += 1
        print(f"=== scenario {i}: {len(diffs)} diffs ===")
        for d in diffs[:10]:
            print("   ", d)
print(f"total divergent scenarios: {problems}/{len(c)}")

